export interface ConnectorConfig {
  /** Trello API key from https://trello.com/app-key */
  trelloApiKey: string
  /** Trello API token (generated via OAuth or manual token generation) */
  trelloApiToken: string
  /** ID of the Trello card to add the checklist to */
  trelloCardId: string
  /** Optional name for the checklist (default: "Attendee Emails") */
  checklistName?: string
  /** Injected fetch for testing */
  fetch?: typeof fetch
}

export interface GoogleCalendarWebhookPayload {
  type: string
  created_at: string
  data: {
    id: string
    startDate: string
    duration: number
    cancelled: boolean
    eventName: string
    location: {
      locationType: string
      onlineMeeting?: {
        url: string
        id: string
        passcode: string
      }
    }
    hosts: Array<{ name: string; email: string }>
    attendees: Array<{
      name?: string
      email: string
      timezone?: string
      type: string
      customQuestionAnswers?: Array<{ question: string; answer: string | string[] }>
    }>
    invite: {
      id: string
      name: string
      inviteType: string
      description: string
    }
  }
}

export interface HandleResult {
  checklistId: string
  checkItemId: string
  attendeeEmail: string
}

function getFetch(config: ConnectorConfig): typeof fetch {
  return config.fetch ?? fetch
}

function buildUrl(base: string, params: Record<string, string>): string {
  const url = new URL(base)
  Object.entries(params).forEach(([key, value]) => {
    url.searchParams.set(key, value)
  })
  return url.toString()
}

export async function handle(
  payload: GoogleCalendarWebhookPayload,
  config: ConnectorConfig,
): Promise<HandleResult> {
  const fetchImpl = getFetch(config)

  // Validate required fields
  if (!payload.data?.attendees?.length) {
    throw new Error('Payload must contain at least one attendee in data.attendees')
  }

  const firstAttendee = payload.data.attendees[0]
  if (!firstAttendee.email) {
    throw new Error('First attendee must have an email field')
  }

  const attendeeEmail = firstAttendee.email
  const checklistName = config.checklistName ?? 'Attendee Emails'

  // Step 1: Create checklist on the card
  const createChecklistUrl = buildUrl('https://api.trello.com/1/checklists', {
    key: config.trelloApiKey,
    token: config.trelloApiToken,
  })

  const checklistResponse = await fetchImpl(createChecklistUrl, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      name: checklistName,
      idCard: config.trelloCardId,
      pos: 'bottom',
    }),
  })

  if (!checklistResponse.ok) {
    throw new Error(
      `Failed to create checklist: ${checklistResponse.status} ${checklistResponse.statusText} at POST /1/checklists`,
    )
  }

  const checklistData = (await checklistResponse.json()) as { id: string }
  const checklistId = checklistData.id

  // Step 2: Add checklist item with attendee email
  const addItemUrl = buildUrl(
    `https://api.trello.com/1/checklists/${checklistId}/checkItems`,
    {
      key: config.trelloApiKey,
      token: config.trelloApiToken,
    },
  )

  const itemResponse = await fetchImpl(addItemUrl, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      name: attendeeEmail,
      checked: false,
    }),
  })

  if (!itemResponse.ok) {
    throw new Error(
      `Failed to add checklist item: ${itemResponse.status} ${itemResponse.statusText} at POST /1/checklists/${checklistId}/checkItems`,
    )
  }

  const itemData = (await itemResponse.json()) as { id: string }
  const checkItemId = itemData.id

  return {
    checklistId,
    checkItemId,
    attendeeEmail,
  }
}

import { describe, it, expect, vi } from 'vitest'
import { handle, ConnectorConfig, GoogleCalendarWebhookPayload } from './connector'
import {
  SOURCE_EXAMPLE,
  TARGET_ENDPOINTS,
  contractFetch,
  fakeFetch,
  jsonResponse,
  RecordedCall,
} from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      trelloApiKey: 'test-key',
      trelloApiToken: 'test-token',
      trelloCardId: 'abc123',
      checklistName: 'Attendee Emails',
      fetch,
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as GoogleCalendarWebhookPayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.attendeeEmail).toBe('jane.doe@example.com')
    expect(result.checklistId).toBe('checklist_id_123')
    expect(result.checkItemId).toBe('checkitem_id_789')
  })
})

describe('handle', () => {
  it('creates checklist and adds item with first attendee email on happy path', async () => {
    const { fetch, calls } = fakeFetch((req: RecordedCall) => {
      if (req.url.includes('/checklists') && !req.url.includes('/checkItems')) {
        return jsonResponse({ id: 'checklist_456', name: 'Attendee Emails' }, 201)
      }
      if (req.url.includes('/checkItems')) {
        return jsonResponse({ id: 'checkitem_789', name: 'jane.doe@example.com' }, 201)
      }
      return jsonResponse({ error: 'not found' }, 404)
    })

    const config: ConnectorConfig = {
      trelloApiKey: 'test-key',
      trelloApiToken: 'test-token',
      trelloCardId: 'card_123',
      fetch,
    }

    const payload: GoogleCalendarWebhookPayload = {
      type: 'event.created',
      created_at: '2025-02-09T14:46:11.469Z',
      data: {
        id: 'evt_1',
        startDate: '2025-02-12T20:30:00.000Z',
        duration: 30,
        cancelled: false,
        eventName: 'Test Event',
        location: { locationType: 'zoom', onlineMeeting: { url: '', id: '', passcode: '' } },
        hosts: [{ name: 'Host', email: 'host@example.com' }],
        attendees: [
          { name: 'Jane Doe', email: 'jane.doe@example.com', timezone: 'America/New_York', type: 'invitee' },
          { email: 'guest@example.com', type: 'guest' },
        ],
        invite: { id: 'inv_1', name: '30 min', inviteType: 'one_on_one', description: 'Test' },
      },
    }

    const result = await handle(payload, config)

    expect(result.attendeeEmail).toBe('jane.doe@example.com')
    expect(result.checklistId).toBe('checklist_456')
    expect(result.checkItemId).toBe('checkitem_789')
    expect(calls).toHaveLength(2)

    // Verify first call - create checklist
    expect(calls[0].method).toBe('POST')
    expect(calls[0].url).toContain('/1/checklists')
    expect(calls[0].url).toContain('key=test-key')
    expect(calls[0].url).toContain('token=test-token')
    expect(calls[0].json).toEqual({
      name: 'Attendee Emails',
      idCard: 'card_123',
      pos: 'bottom',
    })

    // Verify second call - add check item
    expect(calls[1].method).toBe('POST')
    expect(calls[1].url).toContain('/1/checklists/checklist_456/checkItems')
    expect(calls[1].url).toContain('key=test-key')
    expect(calls[1].url).toContain('token=test-token')
    expect(calls[1].json).toEqual({
      name: 'jane.doe@example.com',
      checked: false,
    })
  })

  it('uses custom checklist name from config', async () => {
    const { fetch, calls } = fakeFetch((req: RecordedCall) => {
      if (req.url.includes('/checklists') && !req.url.includes('/checkItems')) {
        return jsonResponse({ id: 'checklist_456' }, 201)
      }
      if (req.url.includes('/checkItems')) {
        return jsonResponse({ id: 'checkitem_789' }, 201)
      }
      return jsonResponse({ error: 'not found' }, 404)
    })

    const config: ConnectorConfig = {
      trelloApiKey: 'test-key',
      trelloApiToken: 'test-token',
      trelloCardId: 'card_123',
      checklistName: 'Custom Checklist Name',
      fetch,
    }

    const payload: GoogleCalendarWebhookPayload = {
      type: 'event.created',
      created_at: '2025-02-09T14:46:11.469Z',
      data: {
        id: 'evt_1',
        startDate: '2025-02-12T20:30:00.000Z',
        duration: 30,
        cancelled: false,
        eventName: 'Test Event',
        location: { locationType: 'zoom', onlineMeeting: { url: '', id: '', passcode: '' } },
        hosts: [{ name: 'Host', email: 'host@example.com' }],
        attendees: [{ name: 'Jane', email: 'jane@example.com', type: 'invitee' }],
        invite: { id: 'inv_1', name: '30 min', inviteType: 'one_on_one', description: 'Test' },
      },
    }

    await handle(payload, config)

    expect(calls[0].json).toEqual({
      name: 'Custom Checklist Name',
      idCard: 'card_123',
      pos: 'bottom',
    })
  })

  it('throws when attendees array is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))

    const config: ConnectorConfig = {
      trelloApiKey: 'test-key',
      trelloApiToken: 'test-token',
      trelloCardId: 'card_123',
      fetch,
    }

    const payload = {
      type: 'event.created',
      created_at: '2025-02-09T14:46:11.469Z',
      data: {
        id: 'evt_1',
        startDate: '2025-02-12T20:30:00.000Z',
        duration: 30,
        cancelled: false,
        eventName: 'Test Event',
        location: { locationType: 'zoom', onlineMeeting: { url: '', id: '', passcode: '' } },
        hosts: [{ name: 'Host', email: 'host@example.com' }],
        attendees: [],
        invite: { id: 'inv_1', name: '30 min', inviteType: 'one_on_one', description: 'Test' },
      },
    } as unknown as GoogleCalendarWebhookPayload

    await expect(handle(payload, config)).rejects.toThrow(
      'Payload must contain at least one attendee in data.attendees',
    )
  })

  it('throws when first attendee has no email', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))

    const config: ConnectorConfig = {
      trelloApiKey: 'test-key',
      trelloApiToken: 'test-token',
      trelloCardId: 'card_123',
      fetch,
    }

    const payload: GoogleCalendarWebhookPayload = {
      type: 'event.created',
      created_at: '2025-02-09T14:46:11.469Z',
      data: {
        id: 'evt_1',
        startDate: '2025-02-12T20:30:00.000Z',
        duration: 30,
        cancelled: false,
        eventName: 'Test Event',
        location: { locationType: 'zoom', onlineMeeting: { url: '', id: '', passcode: '' } },
        hosts: [{ name: 'Host', email: 'host@example.com' }],
        attendees: [{ name: 'No Email', type: 'invitee' }],
        invite: { id: 'inv_1', name: '30 min', inviteType: 'one_on_one', description: 'Test' },
      },
    }

    await expect(handle(payload, config)).rejects.toThrow(
      'First attendee must have an email field',
    )
  })

  it('throws descriptive error when checklist creation fails', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ error: 'Unauthorized' }, 401))

    const config: ConnectorConfig = {
      trelloApiKey: 'test-key',
      trelloApiToken: 'test-token',
      trelloCardId: 'card_123',
      fetch,
    }

    const payload: GoogleCalendarWebhookPayload = {
      type: 'event.created',
      created_at: '2025-02-09T14:46:11.469Z',
      data: {
        id: 'evt_1',
        startDate: '2025-02-12T20:30:00.000Z',
        duration: 30,
        cancelled: false,
        eventName: 'Test Event',
        location: { locationType: 'zoom', onlineMeeting: { url: '', id: '', passcode: '' } },
        hosts: [{ name: 'Host', email: 'host@example.com' }],
        attendees: [{ name: 'Jane', email: 'jane@example.com', type: 'invitee' }],
        invite: { id: 'inv_1', name: '30 min', inviteType: 'one_on_one', description: 'Test' },
      },
    }

    await expect(handle(payload, config)).rejects.toThrow(
      'Failed to create checklist: 401 Unauthorized at POST /1/checklists',
    )
    expect(calls).toHaveLength(1)
  })

  it('throws descriptive error when check item creation fails', async () => {
    const { fetch, calls } = fakeFetch((req: RecordedCall) => {
      if (req.url.includes('/checklists') && !req.url.includes('/checkItems')) {
        return jsonResponse({ id: 'checklist_456' }, 201)
      }
      return jsonResponse({ error: 'Forbidden' }, 403)
    })

    const config: ConnectorConfig = {
      trelloApiKey: 'test-key',
      trelloApiToken: 'test-token',
      trelloCardId: 'card_123',
      fetch,
    }

    const payload: GoogleCalendarWebhookPayload = {
      type: 'event.created',
      created_at: '2025-02-09T14:46:11.469Z',
      data: {
        id: 'evt_1',
        startDate: '2025-02-12T20:30:00.000Z',
        duration: 30,
        cancelled: false,
        eventName: 'Test Event',
        location: { locationType: 'zoom', onlineMeeting: { url: '', id: '', passcode: '' } },
        hosts: [{ name: 'Host', email: 'host@example.com' }],
        attendees: [{ name: 'Jane', email: 'jane@example.com', type: 'invitee' }],
        invite: { id: 'inv_1', name: '30 min', inviteType: 'one_on_one', description: 'Test' },
      },
    }

    await expect(handle(payload, config)).rejects.toThrow(
      'Failed to add checklist item: 403 Forbidden at POST /1/checklists/checklist_456/checkItems',
    )
    expect(calls).toHaveLength(2)
  })

  it('passes auth as query parameters key and token', async () => {
    const { fetch, calls } = fakeFetch((req: RecordedCall) => {
      if (req.url.includes('/checklists') && !req.url.includes('/checkItems')) {
        return jsonResponse({ id: 'checklist_456' }, 201)
      }
      if (req.url.includes('/checkItems')) {
        return jsonResponse({ id: 'checkitem_789' }, 201)
      }
      return jsonResponse({ error: 'not found' }, 404)
    })

    const config: ConnectorConfig = {
      trelloApiKey: 'my-api-key',
      trelloApiToken: 'my-api-token',
      trelloCardId: 'card_123',
      fetch,
    }

    const payload: GoogleCalendarWebhookPayload = {
      type: 'event.created',
      created_at: '2025-02-09T14:46:11.469Z',
      data: {
        id: 'evt_1',
        startDate: '2025-02-12T20:30:00.000Z',
        duration: 30,
        cancelled: false,
        eventName: 'Test Event',
        location: { locationType: 'zoom', onlineMeeting: { url: '', id: '', passcode: '' } },
        hosts: [{ name: 'Host', email: 'host@example.com' }],
        attendees: [{ name: 'Jane', email: 'jane@example.com', type: 'invitee' }],
        invite: { id: 'inv_1', name: '30 min', inviteType: 'one_on_one', description: 'Test' },
      },
    }

    await handle(payload, config)

    // Verify both calls have key and token as query params
    for (const call of calls) {
      expect(call.url).toContain('key=my-api-key')
      expect(call.url).toContain('token=my-api-token')
    }
  })
})

